const texts = content.filter(item => item?.type === 'output_text');
if (!texts.length || !texts.every(item => typeof item.text === 'string')) fail('missing or invalid output text');
let result;
try { result = JSON.parse(texts.map(item => item.text).join('')); }
catch { fail('agent returned invalid JSON'); }
if (!result || typeof result !== 'object' || Array.isArray(result)) fail('result must be an object');
const problems = [];
if (typeof result.summary !== 'string') problems.push('summary must be a string');
else {
  if (!result.summary.trim()) problems.push('summary is empty');
  if (result.summary.length > limits.summary) problems.push(`summary has ${result.summary.length} characters; maximum is ${limits.summary}`);
}
if (!Array.isArray(result.details)) problems.push('details must be an array');
else {
  if (result.details.length > limits.count) problems.push(`details contains ${result.details.length} items; maximum is ${limits.count}`);
  result.details.forEach((detail, index) => {
    if (typeof detail !== 'string') problems.push(`detail ${index + 1} must be a string`);
    else if (detail.length > limits.detail) problems.push(`detail ${index + 1} has ${detail.length} characters; maximum is ${limits.detail}`);
  });
}
if (problems.length) fail('validation failed: ' + problems.join('; '));
result = { summary: result.summary.trim(), details: [...result.details] };
const verdictPattern =
  /^(READY FOR IMPLEMENTATION:|NEEDS REVISION:)/;

if (!verdictPattern.test(result.summary)) {
  throw new Error('Synthesizer summary is missing a proposal verdict');
}

const qaSummary = state.agents?.qa?.summary;

if (
  typeof qaSummary !== 'string' ||
  !verdictPattern.test(qaSummary.trim())
) {
  throw new Error('Previous QA report is missing a valid proposal verdict');
}

if (
  qaSummary.trim().startsWith('NEEDS REVISION:') &&
  !result.summary.startsWith('NEEDS REVISION:')
) {
  result.summary =
    'NEEDS REVISION: QA identified unresolved issues. ' +
    result.summary.replace(
      /^(READY FOR IMPLEMENTATION:|NEEDS REVISION:)\s*/,
      ''
    );
}

// Re-aggregate the stored QA review to re-verify this synthesis. The QA review sub-workflow
// owns that logic; mode "result" skips the model call and aggregates the supplied object.
return [{json:{mode:'result', payload:{workflowDeclaration:state.qaReview?.workflowDeclaration,scope:state.qaReview?.scope,identityColumns:state.qaReview?.identityColumns,verificationClaims:state.qaReview?.verificationClaims,infrastructureClaims:state.qaReview?.infrastructureClaims,riskScan:state.qaReview?.riskScan,findings:state.qaReview?.findings}, state, synthesisResult:result}}];

const { runId, idea } = $json.body || {};
if (typeof runId !== 'string' || !runId.trim() || runId.length > 200 || typeof idea !== 'string' || !idea.trim() || idea.length > 5000) throw new Error('Invalid request');
return [{ json: { runId, idea: idea.trim(), model: 'gpt-4.1-mini', agents: {} } }];

