const call = $('Collect Synthesizer').first().json;
const state = call.state;
const result = call.synthesisResult;
const reviewed = $json;
const limits = { summary: 2000, detail: 1800, count: 7 };

if (reviewed.implementationBlockers.length) result.summary = reviewed.report.summary;
else if (reviewed.executionBlockers.length) result.summary = result.summary.replace(/ Live execution blocked:[\s\S]*$/, '') + ' Live execution blocked: ' + reviewed.executionBlockers.join(', ') + '.';
const blockerIndex = result.details.findIndex(detail => detail.startsWith('BLOCKERS/ASSUMPTIONS:'));
if (blockerIndex < 0) throw new Error('Synthesizer: missing BLOCKERS/ASSUMPTIONS detail');
result.details[blockerIndex] = 'BLOCKERS/ASSUMPTIONS: ' + (reviewed.executionBlockers.length ? reviewed.findings.filter(f => reviewed.executionBlockers.includes(f.checkId)).map(f => f.checkId + ' [' + (reviewed.implementationBlockers.includes(f.checkId) ? 'implementation' : 'live execution only') + '] ' + f.responsibleRole + ': ' + f.requiredCorrection).join('; ') : 'No QA blockers. This planning review does not certify live execution.');
if (reviewed.implementationBlockers.length) {
  const replaceDetail = (label, text) => {
    const index = result.details.findIndex(detail => detail.startsWith(label));
    if (index < 0) throw new Error('Synthesizer: missing ' + label + ' detail');
    result.details[index] = label + ' ' + text;
  };
  replaceDetail('FIRST INCREMENT:', 'Revise the planning handoff to resolve the QA implementation blockers. No implementation or deployment is approved by this review.');
  replaceDetail('ORDERED CHANGES:', reviewed.findings.filter(f => reviewed.implementationBlockers.includes(f.checkId)).map(f => f.responsibleRole + ': ' + f.requiredCorrection).join('; '));
  replaceDetail('ACCEPTANCE:', 'Review the revised design against every QA correction, then repeat QA. Planned implementation checks remain unexecuted; live execution requires the listed prerequisites.');
}
if (result.summary.length > limits.summary) throw new Error('Synthesizer: final summary exceeds 2000 characters');
if (result.details.some(d => d.length > limits.detail)) throw new Error('Synthesizer: final detail exceeds 1800 characters');
if (
  !state.architecture?.version ||
  !state.architecture?.repositoryRevision
) {
  throw new Error('Architecture context is missing its version or repository revision');
}

// This adds one system-generated detail after validating
// the model's maximum of seven. Nuxt accepts this eighth item.
result.details.unshift(
  'CONTEXT: architecture ' +
  state.architecture.version +
  '; repository ' +
  state.architecture.repositoryRevision +
  '. Planning only; implementation and tests not executed. ' +
  'See QA report for blockers.'
);

return [{
  json: {
    runId: state.runId,
    status: 'complete',
    agents: state.agents,
    final: result
  }
}];
